/**
 * Gemini Hook Adapter
 * Handles Gemini-specific hook data while preserving all fields
 */

import { SupportedAgent } from '../../supported-agents';
import {
  UniversalAgentSessionEvent,
  NormalizedEventType,
} from '../../types/UniversalAgentSessionEvent';
import { extractFilePathsFromToolInput, getFileOperation } from '../../types/PathNormalization';
import { AgentEventProcessor } from '../AgentEventProcessor';

import type { GeminiHookInput } from './types';
import {
  isGeminiPreToolUse,
  isGeminiPostToolUse,
  isGeminiStopHook,
  isGeminiNotification,
  isGeminiSubagentStop,
  isGeminiPreCompact,
} from './types';

// Helper to safely extract values
function getString(value: unknown, defaultValue: string = ''): string {
  return typeof value === 'string' ? value : defaultValue;
}

function getNumber(value: unknown, defaultValue: number = 0): number {
  return typeof value === 'number' ? value : defaultValue;
}

export class GeminiEventProcessor implements AgentEventProcessor<GeminiHookInput> {
  /**
   * Normalize Gemini hook data into standardized format
   */
  normalize(rawData: GeminiHookInput): UniversalAgentSessionEvent {
    const timestamp = getNumber((rawData as any).timestamp, Date.now());
    let eventType: NormalizedEventType = 'unknown';
    let toolName: string | undefined;
    let toolInput: unknown | undefined;
    let toolOutput: unknown | undefined;
    const eventData: Record<string, unknown> = {};

    // Check hook_event_name to determine event type
    const hookEventName = (rawData as any).hook_event_name;

    if (hookEventName) {
      switch (hookEventName) {
        case 'PreToolUse':
          eventType = 'pre-tool-use';
          if (isGeminiPreToolUse(rawData)) {
            toolName = rawData.tool_name;
            // Parse tool_use_input if it's a JSON string
            try {
              toolInput =
                typeof rawData.tool_input === 'string'
                  ? JSON.parse(rawData.tool_input)
                  : rawData.tool_input;
            } catch {
              toolInput = rawData.tool_input;
            }
          }
          break;

        case 'PostToolUse':
          eventType = 'post-tool-use';
          if (isGeminiPostToolUse(rawData)) {
            toolName = rawData.tool_name;
            // Parse tool_use_input if it's a JSON string
            try {
              toolInput =
                typeof rawData.tool_input === 'string'
                  ? JSON.parse(rawData.tool_input)
                  : rawData.tool_input;
            } catch {
              toolInput = rawData.tool_input;
            }
            toolOutput = rawData.tool_response;
          }
          break;

        case 'Notification':
          eventType = 'notification';
          eventData.message = (rawData as any).message;
          break;

        case 'UserPromptSubmit':
          eventType = 'user-prompt-submit';
          eventData.prompt = (rawData as any).prompt;
          break;

        case 'Stop':
          eventType = 'stop';
          eventData.trigger = (rawData as any).trigger;
          eventData.reason = (rawData as any).reason;
          eventData.stopHookActive = (rawData as any).stop_hook_active;
          break;

        case 'SubagentStop':
          eventType = 'subagent-stop';
          eventData.taskId = (rawData as any).task_id;
          eventData.stopHookActive = (rawData as any).stop_hook_active;
          break;

        case 'PreCompact':
          eventType = 'pre-compact';
          eventData.trigger = (rawData as any).trigger;
          eventData.customInstructions = (rawData as any).custom_instructions;
          eventData.contextSize = (rawData as any).context_size;
          break;

        case 'SessionStart':
          eventType = 'session-start';
          eventData.source = (rawData as any).source;
          eventData.resumeFrom = (rawData as any).resume_from;
          break;
      }
    } else {
      // Fallback for old format using isGemini* functions
      if (isGeminiStopHook(rawData)) {
        eventType = 'stop';
      } else if (isGeminiPreToolUse(rawData)) {
        eventType = 'pre-tool-use';
        toolName = rawData.tool_name;
        toolInput = rawData.tool_input || rawData.params;
      } else if (isGeminiPostToolUse(rawData)) {
        eventType = 'post-tool-use';
        toolName = rawData.tool_name;
        toolInput = rawData.tool_input || rawData.params;
        toolOutput = (rawData as any).tool_response;
      } else if (isGeminiNotification(rawData)) {
        eventType = 'notification';
        eventData.message = (rawData as any).message;
      } else if (isGeminiSubagentStop(rawData)) {
        eventType = 'subagent-stop';
      } else if (isGeminiPreCompact(rawData)) {
        eventType = 'pre-compact';
        eventData.trigger = (rawData as any).trigger;
      }
    }

    // Build normalized event
    const normalized: UniversalAgentSessionEvent = {
      eventType,
      sessionId: getString(
        (rawData as any).session_id,
        process.env.GEMINI_SESSION_ID || `gemini-${Date.now()}`,
      ),
      workingDirectory: getString(
        (rawData as any).working_directory,
        process.env.GEMINI_WORKING_DIRECTORY || process.cwd(),
      ),
      transcriptPath: getString((rawData as any).transcript_path),
      timestamp,
      provider: SupportedAgent.GEMINI,
      raw: rawData,
    };

    // Add optional fields
    if (toolName) normalized.toolName = toolName;
    if (toolInput !== undefined) normalized.toolInput = toolInput;
    if (toolOutput !== undefined) normalized.toolOutput = toolOutput;
    if (Object.keys(eventData).length > 0) normalized.data = eventData;

    // Extract file paths for tool events
    if (toolName && toolInput) {
      const extractedPaths = extractFilePathsFromToolInput(toolName, toolInput);
      if (extractedPaths.length > 0) {
        // Set operation at root level
        normalized.operation = getFileOperation(toolName);

        // Set raw file paths for later normalization
        normalized.rawFilePaths = extractedPaths;
      }
    }

    return normalized;
  }

  /**
   * Extract tool information if this is a tool event
   * @deprecated Use normalized event's toolName and toolInput
   */
  extractToolInfo(event: any): { toolName: string; toolInput: unknown } | null {
    if (event.tool_name) {
      return {
        toolName: event.tool_name,
        toolInput: event.tool_input || event.tool_use_input || event.params || {},
      };
    }
    return null;
  }
}
