/**
 * Agent Configuration Utilities
 * Functions for configuring agent settings with hooks
 */

import type { SupportedAgent } from './supported-agents';

/**
 * Hook types supported by Claude
 */
export const CLAUDE_HOOK_TYPES = [
  'PreToolUse',
  'PostToolUse',
  'Notification',
  'Stop',
  'SubagentStop',
] as const;

export type ClaudeHookType = (typeof CLAUDE_HOOK_TYPES)[number];

/**
 * Hook types supported by Gemini
 */
export const GEMINI_HOOK_TYPES = [
  'PreToolUse',
  'PostToolUse',
  'Stop',
  'Notification',
  'SubagentStop',
  'PreCompact',
] as const;

export type GeminiHookType = (typeof GEMINI_HOOK_TYPES)[number];

/**
 * Hook configuration for a specific hook type
 */
export interface HookMatcher {
  matcher: string;
  hooks: Array<{
    type: 'command';
    command: string;
    timeout?: number;
  }>;
}

/**
 * Claude hooks configuration
 */
export interface ClaudeHooksConfig {
  PreToolUse?: HookMatcher[];
  PostToolUse?: HookMatcher[];
  Notification?: HookMatcher[];
  Stop?: HookMatcher[];
  SubagentStop?: HookMatcher[];
}

/**
 * Claude settings structure
 */
export interface ClaudeSettings {
  hooks?: ClaudeHooksConfig;
  mcpServers?: Record<string, any>;
  [key: string]: unknown; // Other settings
}
/**
 * Claude settings structure
 */
export interface ClaudeDotJson {
  mcpServers?: Record<string, any>;
  [key: string]: unknown; // Other settings
}

/**
 * Configure hooks for Claude agent
 * Adds or updates hooks configuration to register all hook types with the provided script
 *
 * @param settings - Current Claude settings object
 * @param hookScriptPath - Full path to the hook script
 * @returns Modified settings object with hooks configured
 */
export function configureClaudeHooks(
  settings: ClaudeSettings,
  hookScriptPath: string,
): ClaudeSettings {
  // Create a copy of settings to avoid mutation
  const updatedSettings = JSON.parse(JSON.stringify(settings));

  // Initialize hooks if not present
  if (!updatedSettings.hooks) {
    updatedSettings.hooks = {};
  }

  // Configure each hook type to use our script with a wildcard matcher
  // TODO: Check for node in path
  const hookCommand = {
    type: 'command' as const,
    command: `node ${hookScriptPath}`,
    timeout: 30, // 30 seconds timeout
  };

  // Add hook configuration for each type
  CLAUDE_HOOK_TYPES.forEach(hookType => {
    // Initialize array if not present
    if (!updatedSettings.hooks[hookType]) {
      updatedSettings.hooks[hookType] = [];
    }

    // Check if our hook already exists
    const existingHookIndex = updatedSettings.hooks[hookType].findIndex(
      (matcher: HookMatcher) =>
        matcher.matcher === '*' && matcher.hooks.some(h => h.command.includes(hookScriptPath)),
    );

    if (existingHookIndex === -1) {
      // Add new hook configuration with wildcard matcher
      updatedSettings.hooks[hookType].push({
        matcher: '*', // Match all events
        hooks: [hookCommand],
      });
    } else {
      // Update existing hook configuration
      updatedSettings.hooks[hookType][existingHookIndex] = {
        matcher: '*',
        hooks: [hookCommand],
      };
    }
  });

  return updatedSettings;
}

/**
 * Remove hooks configuration for a specific script
 *
 * @param settings - Current Claude settings object
 * @param hookScriptPath - Full path to the hook script to remove
 * @returns Modified settings object with hooks removed
 */
export function removeClaudeHooks(
  settings: ClaudeSettings,
  hookScriptPath: string,
): ClaudeSettings {
  // Create a copy of settings to avoid mutation
  console.log('removeClaudeHooks', hookScriptPath);
  const updatedSettings = JSON.parse(JSON.stringify(settings));

  if (!updatedSettings.hooks) {
    return updatedSettings;
  }

  // Remove hook configuration for each type
  CLAUDE_HOOK_TYPES.forEach(hookType => {
    if (!updatedSettings.hooks[hookType]) {
      return;
    }

    // Filter out matchers that contain our hook script
    updatedSettings.hooks[hookType] = updatedSettings.hooks[hookType].filter(
      (matcher: HookMatcher) => {
        // Keep the matcher if it doesn't contain our hook script
        matcher.hooks = matcher.hooks.filter(h => !h.command.includes(hookScriptPath));
        // Only keep the matcher if it still has hooks
        return matcher.hooks.length > 0;
      },
    );

    // Remove the hook type array if empty
    if (updatedSettings.hooks[hookType].length === 0) {
      delete updatedSettings.hooks[hookType];
    }
  });

  // Remove hooks object if empty
  if (Object.keys(updatedSettings.hooks).length === 0) {
    delete updatedSettings.hooks;
  }

  return updatedSettings;
}

/**
 * Check if a settings object has a specific hook script configured
 *
 * @param settings - Claude settings object
 * @param hookScriptPath - Full path to the hook script
 * @returns True if the hook script is configured
 */
export function hasClaudeHook(settings: ClaudeSettings, hookScriptPath: string): boolean {
  if (!settings.hooks) {
    return false;
  }

  return CLAUDE_HOOK_TYPES.some(hookType => {
    const matchers = settings.hooks?.[hookType];
    if (!matchers) return false;

    return matchers.some((matcher: HookMatcher) =>
      matcher.hooks.some(h => h.command.includes(hookScriptPath)),
    );
  });
}

/**
 * Count total number of hooks configured
 *
 * @param settings - Claude settings object
 * @returns Total number of hook commands configured
 */
export function countClaudeHooks(settings: ClaudeSettings): number {
  if (!settings.hooks) {
    return 0;
  }

  let count = 0;
  CLAUDE_HOOK_TYPES.forEach(hookType => {
    const matchers = settings.hooks?.[hookType];
    if (matchers) {
      matchers.forEach((matcher: HookMatcher) => {
        count += matcher.hooks.length;
      });
    }
  });

  return count;
}

/**
 * Get all unique hook scripts configured
 *
 * @param settings - Claude settings object
 * @returns Array of unique hook script paths
 */
export function getClaudeHookScripts(settings: ClaudeSettings): string[] {
  if (!settings.hooks) {
    return [];
  }

  const scripts = new Set<string>();

  CLAUDE_HOOK_TYPES.forEach(hookType => {
    const matchers = settings.hooks?.[hookType];
    if (matchers) {
      matchers.forEach((matcher: HookMatcher) => {
        matcher.hooks.forEach(h => scripts.add(h.command));
      });
    }
  });

  return Array.from(scripts);
}

/**
 * Gemini hook matcher - can be string or object
 */
export type GeminiMatcher = string | { tools?: string[] };

/**
 * Gemini hook configuration
 */
export interface GeminiHookConfig {
  matcher: GeminiMatcher;
  hooks: Array<{
    type: 'command';
    command: string;
    timeout?: number;
  }>;
}

/**
 * Gemini hooks configuration
 */
export interface GeminiHooksConfig {
  PreToolUse?: GeminiHookConfig[];
  PostToolUse?: GeminiHookConfig[];
  Stop?: GeminiHookConfig[];
  Notification?: GeminiHookConfig[];
  SubagentStop?: GeminiHookConfig[];
  PreCompact?: GeminiHookConfig[];
}

/**
 * Gemini settings structure
 */
export interface GeminiSettings {
  version?: string;
  hooks?: GeminiHooksConfig;
  mcpServers?: Record<string, any>;
  [key: string]: unknown;
}

/**
 * Configure hooks for Gemini agent
 */
export function configureGeminiHooks(
  settings: GeminiSettings,
  hookScriptPath: string,
): GeminiSettings {
  const updatedSettings = JSON.parse(JSON.stringify(settings));

  if (!updatedSettings.hooks) {
    updatedSettings.hooks = {};
  }

  // Gemini uses tool name matchers for different hook types
  const hookCommand = {
    type: 'command' as const,
    command: hookScriptPath,
    timeout: 30000, // 30 seconds timeout
  };

  // Configure all available Gemini hook types
  GEMINI_HOOK_TYPES.forEach(hookType => {
    // Initialize array if not present
    if (!updatedSettings.hooks[hookType]) {
      updatedSettings.hooks[hookType] = [];
    }

    // Check if our hook already exists
    const existingHookIndex = updatedSettings.hooks[hookType].findIndex(
      (config: GeminiHookConfig) =>
        config.hooks && config.hooks.some(h => h.command === hookScriptPath),
    );

    if (existingHookIndex === -1) {
      // Add hook configuration based on hook type
      let matcher: string;

      switch (hookType) {
        case 'PreToolUse':
        case 'PostToolUse':
          // For tool use hooks, match common file operations
          matcher = 'read_file|write_file|replace|read_many_files|list_files|search_files';
          break;
        case 'Stop':
        case 'SubagentStop':
        case 'Notification':
          // These hooks don't need specific matchers
          matcher = '';
          break;
        case 'PreCompact':
          // Pre-compact hook for context management
          matcher = '*';
          break;
        default:
          matcher = '*';
      }

      updatedSettings.hooks[hookType].push({
        matcher,
        hooks: [hookCommand],
      });
    } else {
      // Update existing hook configuration
      updatedSettings.hooks[hookType][existingHookIndex] = {
        matcher: updatedSettings.hooks[hookType][existingHookIndex].matcher,
        hooks: [hookCommand],
      };
    }
  });

  return updatedSettings;
}

/**
 * Remove hooks from Gemini configuration
 */
export function removeGeminiHooks(
  settings: GeminiSettings,
  hookScriptPath: string,
): GeminiSettings {
  const updatedSettings = JSON.parse(JSON.stringify(settings));

  if (!updatedSettings.hooks) {
    return updatedSettings;
  }

  // Remove hooks for each type
  GEMINI_HOOK_TYPES.forEach(hookType => {
    if (!updatedSettings.hooks[hookType]) {
      return;
    }

    // Filter out configurations that contain our hook script
    updatedSettings.hooks[hookType] = updatedSettings.hooks[hookType].filter(
      (config: GeminiHookConfig) => {
        // Ensure config.hooks exists and is an array
        if (!config.hooks || !Array.isArray(config.hooks)) {
          return true; // Keep configs without hooks array
        }

        // Filter out hooks that match our script path
        config.hooks = config.hooks.filter(h => {
          // Ensure the hook has a command property
          if (!h || typeof h.command !== 'string') {
            return true; // Keep hooks without valid command
          }
          return !h.command.includes(hookScriptPath);
        });

        // Only keep the config if it still has hooks
        return config.hooks.length > 0;
      },
    );

    // Remove the hook type array if empty
    if (updatedSettings.hooks[hookType].length === 0) {
      delete updatedSettings.hooks[hookType];
    }
  });

  // Remove hooks object if empty
  if (Object.keys(updatedSettings.hooks).length === 0) {
    delete updatedSettings.hooks;
  }

  return updatedSettings;
}

/**
 * Check if Gemini has hooks configured
 */
export function hasGeminiHook(settings: GeminiSettings, hookScriptPath: string): boolean {
  if (!settings.hooks) {
    return false;
  }

  return GEMINI_HOOK_TYPES.some(hookType => {
    const configs = settings.hooks?.[hookType];
    if (!configs || !Array.isArray(configs)) return false;

    return configs.some((config: GeminiHookConfig) => {
      if (!config.hooks || !Array.isArray(config.hooks)) return false;

      return config.hooks.some(h => {
        if (!h || typeof h.command !== 'string') return false;
        return h.command.includes(hookScriptPath);
      });
    });
  });
}

/**
 * Count Gemini hooks
 */
export function countGeminiHooks(settings: GeminiSettings): number {
  if (!settings.hooks) {
    return 0;
  }

  let count = 0;
  GEMINI_HOOK_TYPES.forEach(hookType => {
    const configs = settings.hooks?.[hookType];
    if (configs) {
      configs.forEach((config: GeminiHookConfig) => {
        count += config.hooks.length;
      });
    }
  });

  return count;
}

/**
 * OpenCode hook types
 */
export const OPENCODE_HOOK_TYPES = [
  'tool_call',
  'file_read',
  'file_edited',
  'web_access',
  'session_stop',
] as const;

export type OpenCodeHookType = (typeof OPENCODE_HOOK_TYPES)[number];

/**
 * OpenCode hook command configuration
 */
export interface OpenCodeHookCommand {
  command: string[];
  environment?: Record<string, string>;
}

/**
 * OpenCode hooks configuration (under experimental.hook)
 */
export interface OpenCodeHooksConfig {
  tool_call?: OpenCodeHookCommand[];
  file_read?: OpenCodeHookCommand[];
  file_edited?: OpenCodeHookCommand[];
  web_access?: OpenCodeHookCommand[];
  session_stop?: OpenCodeHookCommand[];
}

/**
 * OpenCode settings structure
 */
export interface OpenCodeSettings {
  experimental?: {
    anthropicHooks?: OpenCodeHooksConfig;
    [key: string]: unknown;
  };
  [key: string]: unknown;
}

/**
 * Configure hooks for OpenCode agent
 */
export function configureOpenCodeHooks(
  settings: OpenCodeSettings,
  hookScriptPath: string,
): OpenCodeSettings {
  const updatedSettings = JSON.parse(JSON.stringify(settings));

  // Initialize experimental section if not present
  if (!updatedSettings.experimental) {
    updatedSettings.experimental = {};
  }

  // Initialize hooks if not present
  if (!updatedSettings.experimental.anthropicHooks) {
    updatedSettings.experimental.anthropicHooks = {};
  }

  // Create hook command configuration
  const hookCommand: OpenCodeHookCommand = {
    command: ['node', hookScriptPath],
    environment: {
      AGENT_HOOK_TRACK_ALL_TOOLS: 'true',
    },
  };

  // Configure each hook type
  OPENCODE_HOOK_TYPES.forEach(hookType => {
    // Initialize array if not present
    if (!updatedSettings.experimental.anthropicHooks[hookType]) {
      updatedSettings.experimental.anthropicHooks[hookType] = [];
    }

    // Check if our hook already exists
    const existingHookIndex = updatedSettings.experimental.anthropicHooks[hookType].findIndex(
      (cmd: OpenCodeHookCommand) => cmd.command.some(part => part.includes(hookScriptPath)),
    );

    if (existingHookIndex === -1) {
      // Add new hook configuration
      updatedSettings.experimental.anthropicHooks[hookType].push(hookCommand);
    } else {
      // Update existing hook configuration
      updatedSettings.experimental.anthropicHooks[hookType][existingHookIndex] = hookCommand;
    }
  });

  return updatedSettings;
}

/**
 * Remove hooks from OpenCode configuration
 */
export function removeOpenCodeHooks(
  settings: OpenCodeSettings,
  hookScriptPath: string,
): OpenCodeSettings {
  const updatedSettings = JSON.parse(JSON.stringify(settings));

  if (!updatedSettings.experimental?.anthropicHooks) {
    return updatedSettings;
  }

  // Remove hooks for each type
  OPENCODE_HOOK_TYPES.forEach(hookType => {
    if (!updatedSettings.experimental.anthropicHooks[hookType]) {
      return;
    }

    // Filter out configurations that contain our hook script
    updatedSettings.experimental.anthropicHooks[hookType] =
      updatedSettings.experimental.anthropicHooks[hookType].filter((cmd: OpenCodeHookCommand) => {
        // Check if command array contains our hook script path
        if (!cmd.command || !Array.isArray(cmd.command)) {
          return true; // Keep commands without valid command array
        }
        return !cmd.command.some(part => part.includes(hookScriptPath));
      });

    // Remove the hook type array if empty
    if (updatedSettings.experimental.anthropicHooks[hookType].length === 0) {
      delete updatedSettings.experimental.anthropicHooks[hookType];
    }
  });

  // Remove hook object if empty
  if (Object.keys(updatedSettings.experimental.anthropicHooks).length === 0) {
    delete updatedSettings.experimental.anthropicHooks;
  }

  // Remove experimental object if only had hook
  if (updatedSettings.experimental && Object.keys(updatedSettings.experimental).length === 0) {
    delete updatedSettings.experimental;
  }

  return updatedSettings;
}

/**
 * Check if OpenCode has hooks configured
 */
export function hasOpenCodeHook(settings: OpenCodeSettings, hookScriptPath: string): boolean {
  if (!settings.experimental?.anthropicHooks) {
    return false;
  }

  return OPENCODE_HOOK_TYPES.some(hookType => {
    const commands = settings.experimental?.anthropicHooks?.[hookType];
    if (!commands || !Array.isArray(commands)) return false;

    return commands.some((cmd: OpenCodeHookCommand) => {
      if (!cmd.command || !Array.isArray(cmd.command)) return false;
      return cmd.command.some(part => part.includes(hookScriptPath));
    });
  });
}

/**
 * Count OpenCode hooks
 */
export function countOpenCodeHooks(settings: OpenCodeSettings): number {
  if (!settings.experimental?.anthropicHooks) {
    return 0;
  }

  let count = 0;
  OPENCODE_HOOK_TYPES.forEach(hookType => {
    const commands = settings.experimental?.anthropicHooks?.[hookType];
    if (commands && Array.isArray(commands)) {
      count += commands.length;
    }
  });

  return count;
}

/**
 * Combined hook type for all agents
 */
export type HookType = ClaudeHookType | GeminiHookType | OpenCodeHookType;

/**
 * Get the display name for a hook type
 */
export function getHookTypeDisplayName(hookType: HookType): string {
  const displayNames: Record<string, string> = {
    PreToolUse: 'Pre Tool Use',
    PostToolUse: 'Post Tool Use',
    Notification: 'Notification',
    Stop: 'Stop',
    SubagentStop: 'Subagent Stop',
    PreCompact: 'Pre Compact',
    tool_call: 'Tool Call',
    file_read: 'File Read',
    file_edited: 'File Edited',
    web_access: 'Web Access',
    session_stop: 'Session Stop',
  };

  return displayNames[hookType] || hookType;
}

/**
 * Get the description for a hook type
 */
export function getHookTypeDescription(hookType: HookType): string {
  const descriptions: Record<string, string> = {
    PreToolUse: 'Runs before a tool is executed',
    PostToolUse: 'Runs after a tool is executed',
    Notification: 'Handles agent notifications',
    Stop: 'Runs when the agent stops',
    SubagentStop: 'Runs when a subagent stops',
    PreCompact: 'Runs before context compaction',
    tool_call: 'Runs when any tool is called',
    file_read: 'Runs when a file is read',
    file_edited: 'Runs when a file is edited',
    web_access: 'Runs when web content is accessed',
    session_stop: 'Runs when the session stops',
  };

  return descriptions[hookType] || 'Custom hook type';
}

/**
 * Check if a hook type uses matchers
 * Some hook types (like Stop) don't use matchers
 */
export function hookTypeUsesMatchers(hookType: HookType): boolean {
  const noMatcherTypes = ['Stop', 'SubagentStop', 'session_stop'];
  return !noMatcherTypes.includes(hookType);
}

/**
 * Get the default matcher for a hook type
 */
export function getDefaultMatcher(hookType: HookType): string {
  if (!hookTypeUsesMatchers(hookType)) {
    return '';
  }
  return '*'; // Default to wildcard for most hook types
}

/**
 * Get available hook types for a specific agent
 */
export function getAvailableHookTypes(agent: SupportedAgent): readonly HookType[] {
  switch (agent) {
    case 'claude':
      return CLAUDE_HOOK_TYPES;
    case 'gemini':
      return GEMINI_HOOK_TYPES;
    case 'opencode':
      return OPENCODE_HOOK_TYPES;
    default:
      return [];
  }
}

/**
 * Generic agent settings interface
 */
export interface AgentSettings {
  [key: string]: unknown;
}

/**
 * Configure hooks for any supported agent
 * This is a generic function that delegates to agent-specific implementations
 *
 * @param agent - The agent type
 * @param settings - Current agent settings object
 * @param hookScriptPath - Full path to the hook script
 * @returns Modified settings object with hooks configured
 */
export function configureAgentHooks(
  agent: SupportedAgent,
  settings: AgentSettings,
  hookScriptPath: string,
): AgentSettings {
  switch (agent) {
    case 'claude':
      return configureClaudeHooks(settings as ClaudeSettings, hookScriptPath);
    case 'gemini':
      return configureGeminiHooks(settings as GeminiSettings, hookScriptPath);
    case 'opencode':
      return configureOpenCodeHooks(settings as OpenCodeSettings, hookScriptPath);
    default:
      throw new Error(`Unsupported agent: ${agent}`);
  }
}

/**
 * Remove hooks configuration for any supported agent
 *
 * @param agent - The agent type
 * @param settings - Current agent settings object
 * @param hookScriptPath - Full path to the hook script to remove
 * @returns Modified settings object with hooks removed
 */
export function removeAgentHooks(
  agent: SupportedAgent,
  settings: AgentSettings,
  hookScriptPath: string,
): AgentSettings {
  switch (agent) {
    case 'claude':
      return removeClaudeHooks(settings as ClaudeSettings, hookScriptPath);
    case 'gemini':
      return removeGeminiHooks(settings as GeminiSettings, hookScriptPath);
    case 'opencode':
      return removeOpenCodeHooks(settings as OpenCodeSettings, hookScriptPath);
    default:
      throw new Error(`Unsupported agent: ${agent}`);
  }
}

/**
 * Check if an agent has a specific hook script configured
 *
 * @param agent - The agent type
 * @param settings - Agent settings object
 * @param hookScriptPath - Full path to the hook script
 * @returns True if the hook script is configured
 */
export function hasAgentHook(
  agent: SupportedAgent,
  settings: AgentSettings,
  hookScriptPath: string,
): boolean {
  switch (agent) {
    case 'claude':
      return hasClaudeHook(settings as ClaudeSettings, hookScriptPath);
    case 'gemini':
      return hasGeminiHook(settings as GeminiSettings, hookScriptPath);
    case 'opencode':
      return hasOpenCodeHook(settings as OpenCodeSettings, hookScriptPath);
    default:
      throw new Error(`Unsupported agent: ${agent}`);
  }
}

/**
 * Count total number of hooks configured for an agent
 *
 * @param agent - The agent type
 * @param settings - Agent settings object
 * @returns Total number of hook commands configured
 */
export function countAgentHooks(agent: SupportedAgent, settings: AgentSettings): number {
  switch (agent) {
    case 'claude':
      return countClaudeHooks(settings as ClaudeSettings);
    case 'gemini':
      return countGeminiHooks(settings as GeminiSettings);
    case 'opencode':
      return countOpenCodeHooks(settings as OpenCodeSettings);
    default:
      throw new Error(`Unsupported agent: ${agent}`);
  }
}
