/**
 * Claude Hook Types
 * Based on https://docs.anthropic.com/en/docs/claude-code/hooks
 */

export interface ClaudeHookData {
  session_id: string;
  transcript_path: string;
  cwd: string;
  hook_event_name: string;
  tool_name: string;
  tool_input: Record<string, unknown>;
}

export interface ClaudePreToolUseData extends ClaudeHookData {
  hook_event_name: 'PreToolUse';
}

export interface ClaudePostToolUseData extends ClaudeHookData {
  hook_event_name: 'PostToolUse';
  tool_response?: unknown;
}

export interface ClaudeStopHookData {
  session_id: string;
  transcript_path: string;
  cwd: string;
  hook_event_name: 'claude_stop_hook';
}

export type ClaudeHookInput = ClaudePreToolUseData | ClaudePostToolUseData | ClaudeStopHookData;

/**
 * Claude tool names as documented
 */
export const CLAUDE_TOOLS = {
  READ: 'Read',
  WRITE: 'Write',
  EDIT: 'Edit',
  MULTI_EDIT: 'MultiEdit',
  WEB_FETCH: 'WebFetch',
  WEB_SEARCH: 'WebSearch',
  BASH: 'Bash',
  GREP: 'Grep',
  GLOB: 'Glob',
  LS: 'LS',
  TODO_WRITE: 'TodoWrite',
  NOTEBOOK_READ: 'NotebookRead',
  NOTEBOOK_EDIT: 'NotebookEdit',
  TASK: 'Task',
  EXIT_PLAN_MODE: 'ExitPlanMode',
} as const;

export type ClaudeToolName = (typeof CLAUDE_TOOLS)[keyof typeof CLAUDE_TOOLS];

/**
 * Type guards
 */
export function isClaudePreToolUse(data: unknown): data is ClaudePreToolUseData {
  return (
    typeof data === 'object' &&
    data !== null &&
    'hook_event_name' in data &&
    (data as { hook_event_name: unknown }).hook_event_name === 'PreToolUse'
  );
}

export function isClaudePostToolUse(data: unknown): data is ClaudePostToolUseData {
  return (
    typeof data === 'object' &&
    data !== null &&
    'hook_event_name' in data &&
    (data as { hook_event_name: unknown }).hook_event_name === 'PostToolUse'
  );
}

export function isClaudeStopHook(data: unknown): data is ClaudeStopHookData {
  return (
    typeof data === 'object' &&
    data !== null &&
    'hook_event_name' in data &&
    (data as { hook_event_name: unknown }).hook_event_name === 'claude_stop_hook'
  );
}
