/**
 * Normalized event structure for all agent session events
 * This provides a consistent interface across different agents (Claude, Gemini, OpenCode, etc.)
 */

import { SupportedAgent } from '../supported-agents';

import { NormalizedPathInfo, FileOperation } from './PathNormalization';

/**
 * Known event types across all agents
 * Using 'unknown' for events we haven't categorized yet
 */
export type NormalizedEventType =
  | 'pre-tool-use'
  | 'post-tool-use'
  | 'notification'
  | 'user-prompt-submit'
  | 'stop'
  | 'subagent-stop'
  | 'pre-compact'
  | 'session-start'
  | 'lifecycle' // Generic lifecycle events
  | 'unknown'; // For new/unrecognized events

/**
 * Common tool names across agents
 * This is a union of known tools, but we accept string for flexibility
 */
export type CommonToolName =
  | 'Task'
  | 'Bash'
  | 'Glob'
  | 'Grep'
  | 'Read'
  | 'Edit'
  | 'MultiEdit'
  | 'Write'
  | 'WebFetch'
  | 'WebSearch'
  | 'LS'
  | 'TodoWrite'
  | 'NotebookRead'
  | 'NotebookEdit'
  | 'ExitPlanMode'
  | string; // Allow any string for unknown tools

/**
 * Normalized agent session event
 * This is what all agent event processors should return
 */
export interface NormalizedAgentSessionEvent {
  // Event classification
  eventType: NormalizedEventType;

  // Session context (always present)
  sessionId: string;
  workingDirectory: string; // Raw working directory from the event
  normalizedWorkingDirectory?: string; // Git root if in a repository, otherwise same as workingDirectory
  transcriptPath?: string;

  // Timing
  timestamp: number; // When the event occurred

  // Tool information (for tool-related events)
  toolName?: CommonToolName;
  toolInput?: unknown; // Tool-specific input structure
  toolOutput?: unknown; // Tool response (for post-tool-use)

  // File information (for file-related tool events)
  files?: NormalizedPathInfo[];

  // Operation being performed on files
  operation?: FileOperation;

  // Event-specific data
  data?: {
    // For user-prompt-submit
    prompt?: string;

    // For notification
    message?: string;

    // For stop events
    stopHookActive?: boolean;

    // For pre-compact
    trigger?: 'manual' | 'auto';
    customInstructions?: string;

    // For session-start
    source?: 'startup' | 'resume' | 'clear';

    // Generic metadata
    [key: string]: unknown;
  };

  // Original raw event data (preserved for debugging/special processing)
  raw: unknown;

  // Which agent produced this event
  provider: SupportedAgent;
}

/**
 * Type guard to check if an object is a normalized event
 */
export function isNormalizedAgentSessionEvent(obj: unknown): obj is NormalizedAgentSessionEvent {
  if (!obj || typeof obj !== 'object') return false;

  const event = obj as any;
  return (
    typeof event.eventType === 'string' &&
    typeof event.sessionId === 'string' &&
    typeof event.workingDirectory === 'string' &&
    typeof event.timestamp === 'number' &&
    typeof event.provider === 'string' &&
    event.raw !== undefined
  );
}

/**
 * Helper to determine if an event is a tool event
 */
export function isToolEvent(event: NormalizedAgentSessionEvent): boolean {
  return event.eventType === 'pre-tool-use' || event.eventType === 'post-tool-use';
}

/**
 * Helper to determine if an event is a stop event
 */
export function isStopEvent(event: NormalizedAgentSessionEvent): boolean {
  return event.eventType === 'stop' || event.eventType === 'subagent-stop';
}

/**
 * Helper to extract file path from tool input (if applicable)
 */
export function extractFilePath(event: NormalizedAgentSessionEvent): string | undefined {
  if (!isToolEvent(event) || !event.toolInput) return undefined;

  const input = event.toolInput as any;

  // Common file path properties across different tools
  return (
    input.file_path || input.filePath || input.path || input.fileName || input.filename || undefined
  );
}
