/**
 * Centralized service for normalizing paths in universal agent session events
 * Uses a PathNormalizationAdapter to access environment-specific tools
 *
 * Focuses on repository detection and relative path calculation:
 * - Files in current repository: relative path from git root
 * - Files in other repositories: identify repo and provide relative path
 * - Files outside repositories: keep absolute path
 */

import { PathNormalizationAdapter } from '../adapters/PathNormalizationAdapter';
import { UniversalAgentSessionEvent } from '../types/UniversalAgentSessionEvent';
import { RepoNormalizedUniversalAgentSessionEvent } from '../types/RepoNormalizedUniversalAgentSessionEvent';
import { NormalizedPathInfo, RepositoryInfo, validatePlatformSupport, classifyPath } from '../types/PathNormalization';

/**
 * Centralized service for path normalization
 */
export class PathNormalizationService {
  constructor(private adapter: PathNormalizationAdapter) {
    // Validate platform support on initialization
    const systemInfo = adapter.getSystemInfo();
    validatePlatformSupport(systemInfo);
  }

  /**
   * Normalize a universal agent session event by processing its raw file paths
   * @param event Universal agent session event with raw path strings
   * @returns Repository-normalized event with structured path information
   * @throws Error if platform is not supported
   */
  async normalizePaths(
    event: UniversalAgentSessionEvent
  ): Promise<RepoNormalizedUniversalAgentSessionEvent> {
    // OPTIMIZATION: Get repository info for working directory ONCE
    const workingDirRepoInfo = await this.adapter.getRawRepositoryInfo(event.workingDirectory);

    // Prepare event repository context if working directory is in a repo
    const eventRepository = workingDirRepoInfo ? {
      root: workingDirRepoInfo.root,
      remoteUrl: workingDirRepoInfo.remoteUrl,
      owner: workingDirRepoInfo.owner,
      repo: workingDirRepoInfo.repo,
      branch: workingDirRepoInfo.branch,
      headCommit: workingDirRepoInfo.headCommit,
    } : undefined;

    const normalizedPaths: NormalizedPathInfo[] = [];

    // Normalize all raw file paths
    if (event.rawFilePaths && event.rawFilePaths.length > 0) {
      for (const rawPath of event.rawFilePaths) {
        const normalized = await this.normalizePathWithCache(
          rawPath,
          event.workingDirectory,
          workingDirRepoInfo
        );
        normalizedPaths.push(normalized);
      }
    }

    // Normalize working directory to repository root if in a repo
    const normalizedWorkingDirectory = workingDirRepoInfo?.root || event.workingDirectory;

    // Create the normalized event without rawFilePaths
    const { rawFilePaths, ...eventWithoutRawPaths } = event;

    return {
      ...eventWithoutRawPaths,
      repository: eventRepository,
      files: normalizedPaths.length > 0 ? normalizedPaths : undefined,
      normalizedWorkingDirectory,
    };
  }

  /**
   * Normalize a single file path with cached repository info
   * @param filePath Raw file path from the event
   * @param workingDirectory Working directory context
   * @param cachedRepoInfo Cached repository info for working directory (optimization)
   * @returns Normalized path information
   */
  async normalizePathWithCache(
    filePath: string,
    workingDirectory: string,
    cachedRepoInfo: RepositoryInfo | null
  ): Promise<NormalizedPathInfo> {
    // 1. Resolve to absolute path using adapter
    const absolutePath = this.adapter.isAbsolutePath(filePath)
      ? filePath
      : this.adapter.resolvePath(filePath, workingDirectory);

    // 2. OPTIMIZATION: Check if file is in the same repository as working directory
    if (cachedRepoInfo && absolutePath.startsWith(cachedRepoInfo.root)) {
      // File is in the same repository - reuse cached info
      const relativePath = this.adapter.getRelativePath(cachedRepoInfo.root, absolutePath);

      return {
        originalPath: filePath,
        absolutePath,
        context: classifyPath(absolutePath),
        // Include minimal repository info for backward compatibility
        // But omit redundant fields that are already in the event's repository
        repository: {
          gitRoot: cachedRepoInfo.root,
          relativePath,
          // Omit these as they're in the event's repository field:
          // remoteUrl, owner, repo, branch, headCommit
        },
        displayPath: relativePath,
      };
    }

    // 3. File is NOT in the working directory's repository
    // Need to check if it's in a different repository
    const repoInfo = await this.adapter.getRawRepositoryInfo(absolutePath);

    if (repoInfo) {
      // File is in a DIFFERENT repository - include full repo info
      const relativePath = this.adapter.getRelativePath(repoInfo.root, absolutePath);

      return {
        originalPath: filePath,
        absolutePath,
        context: classifyPath(absolutePath),
        repository: {
          gitRoot: repoInfo.root,
          relativePath,
          remoteUrl: repoInfo.remoteUrl,
          owner: repoInfo.owner,
          repo: repoInfo.repo,
        },
        displayPath: relativePath,
      };
    }

    // 4. File is not in any repository - keep absolute path
    return {
      originalPath: filePath,
      absolutePath,
      context: classifyPath(absolutePath),
      displayPath: absolutePath,
    };
  }

  /**
   * Normalize a single file path (legacy method for backward compatibility)
   * @param filePath Raw file path from the event
   * @param workingDirectory Working directory context
   * @returns Normalized path information
   */
  async normalizePath(
    filePath: string,
    workingDirectory: string
  ): Promise<NormalizedPathInfo> {
    // Call the optimized version with no cache (for backward compatibility)
    return this.normalizePathWithCache(filePath, workingDirectory, null);
  }

  /**
   * Normalize working directory to repository root
   * @param workingDirectory Raw working directory path
   * @returns Repository root if in a git repo, otherwise original path
   */
  async normalizeWorkingDirectory(workingDirectory: string): Promise<string> {
    const repoInfo = await this.adapter.getRawRepositoryInfo(workingDirectory);
    return repoInfo?.root || workingDirectory;
  }
}