/**
 * Universal event structure after agent-specific normalization
 * Contains raw path strings that need repository-specific processing
 *
 * This is an intermediate format that bridges agent-specific processors
 * and path normalization services. Agent processors extract raw paths
 * as strings, and the path normalization service enriches them with
 * repository and system context.
 */

import { SupportedAgent } from '../supported-agents';
import { FileOperation } from './PathNormalization';

/**
 * Re-export event types for convenience
 */
export type { NormalizedEventType, CommonToolName } from './NormalizedAgentSessionEvent';
import { NormalizedEventType, CommonToolName } from './NormalizedAgentSessionEvent';

/**
 * Universal event structure after agent-specific normalization
 * Contains raw path strings that need repository-specific processing
 */
export interface UniversalAgentSessionEvent {
  // Event classification (from agent processor)
  eventType: NormalizedEventType;

  // Session context
  sessionId: string;
  workingDirectory: string;
  transcriptPath?: string;

  // Timing
  timestamp: number;

  // Tool information (from agent processor)
  toolName?: CommonToolName;
  toolInput?: unknown;
  toolOutput?: unknown;

  // Raw file paths (extracted by agent processor, not yet normalized)
  rawFilePaths?: string[];

  // Operation type (determined by agent processor)
  operation?: FileOperation;

  // Event-specific data (from agent processor)
  data?: {
    prompt?: string;
    message?: string;
    stopHookActive?: boolean;
    trigger?: 'manual' | 'auto';
    customInstructions?: string;
    source?: 'startup' | 'resume' | 'clear';
    [key: string]: unknown;
  };

  // Original raw event data
  raw: unknown;

  // Which agent produced this event
  provider: SupportedAgent;
}

/**
 * Type guard to check if an object is a universal agent session event
 */
export function isUniversalAgentSessionEvent(obj: unknown): obj is UniversalAgentSessionEvent {
  if (!obj || typeof obj !== 'object') return false;

  const event = obj as any;
  return (
    typeof event.eventType === 'string' &&
    typeof event.sessionId === 'string' &&
    typeof event.workingDirectory === 'string' &&
    typeof event.timestamp === 'number' &&
    typeof event.provider === 'string' &&
    event.raw !== undefined
  );
}