/**
 * Gemini Hook Types
 * Based on Gemini CLI documentation and Claude-compatible structure
 */

export interface GeminiHookData {
  session_id?: string;
  agent_type: 'gemini';
  hook_event_name: string;
  tool_name?: string;
  tool_input?: Record<string, unknown>;
  tool_response?: Record<string, unknown>;
  params?: Record<string, unknown>; // Alternative to tool_input
  working_directory?: string;
  timestamp?: number;
}

export interface GeminiPreToolUseData extends GeminiHookData {
  hook_event_name: 'PreToolUse';
  tool_name: string;
  tool_input: Record<string, unknown>;
}

export interface GeminiPostToolUseData extends GeminiHookData {
  hook_event_name: 'PostToolUse';
  tool_name: string;
  tool_input: Record<string, unknown>;
  tool_response: Record<string, unknown>;
}

export interface GeminiStopHookData extends GeminiHookData {
  hook_event_name: 'Stop';
}

export interface GeminiNotificationData extends GeminiHookData {
  hook_event_name: 'Notification';
  message?: string;
  level?: 'info' | 'warning' | 'error';
}

export interface GeminiSubagentStopData extends GeminiHookData {
  hook_event_name: 'SubagentStop';
  subagent_id?: string;
}

export interface GeminiPreCompactData extends GeminiHookData {
  hook_event_name: 'PreCompact';
  conversation_length?: number;
}

export type GeminiHookInput =
  | GeminiPreToolUseData
  | GeminiPostToolUseData
  | GeminiStopHookData
  | GeminiNotificationData
  | GeminiSubagentStopData
  | GeminiPreCompactData;

/**
 * Gemini tool names (based on README)
 */
export const GEMINI_TOOLS = {
  READ_FILE: 'read_file',
  WRITE_FILE: 'write_file',
  REPLACE: 'replace',
  FIND: 'find',
  GREP: 'grep',
  RUN_SHELL: 'run_shell',
  WEB_FETCH: 'web_fetch',
  GOOGLE_WEB_SEARCH: 'google_web_search',
} as const;

export type GeminiToolName = (typeof GEMINI_TOOLS)[keyof typeof GEMINI_TOOLS];

/**
 * Type guards
 */
export function isGeminiPreToolUse(data: unknown): data is GeminiPreToolUseData {
  return (
    typeof data === 'object' &&
    data !== null &&
    'hook_event_name' in data &&
    'agent_type' in data &&
    (data as { hook_event_name: unknown }).hook_event_name === 'PreToolUse' &&
    (data as { agent_type: unknown }).agent_type === 'gemini'
  );
}

