/**
 * Claude Hook Adapter
 * Handles Claude-specific hook data while preserving all fields
 */

import { SupportedAgent } from '../../supported-agents';
import {
  UniversalAgentSessionEvent,
  NormalizedEventType,
} from '../../types/UniversalAgentSessionEvent';
import {
  extractFilePathsFromTool,
  getFileOperation,
  validatePlatformSupport,
  type SupportedPlatform
} from '../../types/PathNormalization';
import { AgentEventProcessor } from '../AgentEventProcessor';

import type { ClaudeHookInput } from './types';
import { isClaudePreToolUse, isClaudePostToolUse, isClaudeStopHook } from './types';

// Helper to safely extract string values
function getString(value: unknown, defaultValue: string = ''): string {
  return typeof value === 'string' ? value : defaultValue;
}

export class ClaudeEventProcessor implements AgentEventProcessor<ClaudeHookInput> {
  /**
   * Normalize Claude hook data into standardized format
   */
  normalize(rawData: ClaudeHookInput): UniversalAgentSessionEvent {
    const timestamp = Date.now();
    let eventType: NormalizedEventType = 'unknown';
    let toolName: string | undefined;
    let toolInput: unknown | undefined;
    let toolOutput: unknown | undefined;
    const data: Record<string, unknown> = {};

    // Check for new event types first (based on hook_event_name)
    const hookEventName = (rawData as any).hook_event_name;

    if (hookEventName) {
      switch (hookEventName) {
        case 'PreToolUse':
          eventType = 'pre-tool-use';
          if (isClaudePreToolUse(rawData)) {
            toolName = rawData.tool_name;
            toolInput = rawData.tool_input;
          }
          break;
        case 'PostToolUse':
          eventType = 'post-tool-use';
          if (isClaudePostToolUse(rawData)) {
            toolName = rawData.tool_name;
            toolInput = rawData.tool_input;
            toolOutput = (rawData as any).tool_response;
          }
          break;
        case 'Notification':
          eventType = 'notification';
          data.message = (rawData as any).message;
          break;
        case 'UserPromptSubmit':
          eventType = 'user-prompt-submit';
          data.prompt = (rawData as any).prompt;
          break;
        case 'Stop':
          eventType = 'stop';
          data.stopHookActive = (rawData as any).stop_hook_active;
          break;
        case 'SubagentStop':
          eventType = 'subagent-stop';
          data.stopHookActive = (rawData as any).stop_hook_active;
          break;
        case 'PreCompact':
          eventType = 'pre-compact';
          data.trigger = (rawData as any).trigger;
          data.customInstructions = (rawData as any).custom_instructions;
          break;
        case 'SessionStart':
          eventType = 'session-start';
          data.source = (rawData as any).source;
          break;
        case 'claude_stop_hook':
          // Legacy stop hook format
          eventType = 'stop';
          break;
      }
    } else if (isClaudeStopHook(rawData)) {
      // Fallback for old stop hook format
      eventType = 'stop';
    } else if (isClaudePreToolUse(rawData)) {
      eventType = 'pre-tool-use';
      toolName = rawData.tool_name;
      toolInput = rawData.tool_input;
    } else if (isClaudePostToolUse(rawData)) {
      eventType = 'post-tool-use';
      toolName = rawData.tool_name;
      toolInput = rawData.tool_input;
      toolOutput = (rawData as any).tool_response;
    }

    // Build normalized event
    const normalized: UniversalAgentSessionEvent = {
      eventType,
      sessionId: getString((rawData as any).session_id),
      workingDirectory: getString(
        (rawData as any).cwd || (rawData as any).working_directory,
        process.cwd(),
      ),
      transcriptPath: getString((rawData as any).transcript_path),
      timestamp,
      provider: SupportedAgent.CLAUDE,
      raw: rawData,
    };

    // Add optional fields
    if (toolName) normalized.toolName = toolName;
    if (toolInput !== undefined) normalized.toolInput = toolInput;
    if (toolOutput !== undefined) normalized.toolOutput = toolOutput;
    if (Object.keys(data).length > 0) normalized.data = data;

    // Extract file paths using comprehensive extraction
    // Note: We assume Unix-style paths for Claude events
    // Platform validation will happen at the PathNormalizationService level
    try {
      const extractedPaths = extractFilePathsFromTool(
        toolName || '',
        toolInput,
        toolOutput,
        // Don't pass systemInfo here - let the service handle platform validation
      );

      if (extractedPaths.length > 0) {
        // Set operation at root level
        if (toolName) {
          normalized.operation = getFileOperation(toolName);
        }

        // Set raw file paths for later normalization
        normalized.rawFilePaths = extractedPaths;
      }
    } catch (error) {
      // Log extraction errors but don't fail the normalization
      console.warn(
        `[ClaudeEventProcessor] Failed to extract paths for ${toolName}:`,
        error,
      );
    }

    return normalized;
  }

  /**
   * Extract tool information if this is a tool event
   * @deprecated Use normalized event's toolName and toolInput
   */
  extractToolInfo(event: any): { toolName: string; toolInput: unknown } | null {
    if (event.tool_name) {
      return {
        toolName: event.tool_name,
        toolInput: event.tool_input,
      };
    }
    return null;
  }
}
